// Extract ticket data from the webhook payload
const ticket = $input.first().json.body?.ticket || $input.first().json.ticket || $input.first().json;

const id = ticket.id || 'UNKNOWN';
const name = ticket.name || 'Customer';
const email = ticket.email || '';
const issue = ticket.issue || '';
const category = ticket.result?.category || 'General Query';
const priority = ticket.result?.priority || 'Medium';
const team = ticket.result?.team || 'General Support';
const draft = ticket.result?.draft_response || '';
const confidence = ticket.result?.confidence || 0;
const timestamp = ticket.timestamp || new Date().toISOString();

// Determine urgency flag
const isUrgent = priority === 'High';

// Build notification payload
return [{
  json: {
    id,
    name,
    email,
    issue,
    category,
    priority,
    team,
    draft,
    confidence,
    timestamp,
    isUrgent,
    subject: `[${priority} Priority] New ${category} ticket — ${id}`,
    notificationBody: `NEW SUPPORT TICKET\n${'='.repeat(50)}\n\nTicket ID : ${id}\nPriority  : ${priority}${isUrgent ? ' 🚨' : ''}\nCategory  : ${category}\nTeam      : ${team}\nConfidence: ${confidence}%\n\nCustomer  : ${name}\nEmail     : ${email}\n\nISSUE\n-----\n${issue}\n\nDRAFT RESPONSE\n--------------\n${draft}\n\nTimestamp : ${timestamp}\n${'='.repeat(50)}`
  }
}];

const d = $input.first().json;
console.log(`\n📧 [BILLING TEAM] ${d.subject}`);
console.log(d.notificationBody);
return [{ json: { ...d, routed: true, notifiedTeam: 'Billing Team', routedAt: new Date().toISOString() } }];

